"""Playwright functional run of the Work, Replay and Projects pages: saved views and the project picker in the address, counts, the detail pane, j/k, the Undo toast,
the Replay modes, sections and opening step, the project tabs and sort, the Attention strip. Run:
  py D:\\Archeus\\.collab\\testlock.py -- py -I tools\\v2_live_wp_functional.py"""
import os
import sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import v2_live_layout_probe as P
from playwright.sync_api import sync_playwright

ok = []; bad = []
def check(name, cond):
    (ok if cond else bad).append(name)
    print(('PASS ' if cond else 'FAIL ') + name)

port = P.free_port(); srv = P.start_server(port)
base = 'http://127.0.0.1:%d/index.html' % port
try:
    with sync_playwright() as p:
        br = p.chromium.launch()
        def page(hash, w=1440, h=900, extra=''):
            ctx = br.new_context(viewport={'width': w, 'height': h}); pg = ctx.new_page()
            errs = []; pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('console', lambda m: errs.append(m.text) if m.type == 'error' else None)
            pg.goto(base + '?sim=paused&motion=reduced&theme=dark' + extra + '#/' + hash, wait_until='load'); pg.wait_for_timeout(450)
            return ctx, pg, errs
        n = lambda pg, s: pg.locator(s).count()

        # ---- Work: saved views, counts, filter ----
        ctx, pg, errs = page('work')
        counts = pg.evaluate("[...document.querySelectorAll('.wk-tab .tn')].map((e) => Number(e.textContent))")
        check('five saved views with counts, All is the sum', len(counts) == 5 and counts[4] == sum(counts[:4]))
        pg.click('[data-key="work-view-running"]'); pg.wait_for_timeout(250)
        check('a view is in the address and marked', pg.evaluate('location.hash') == '#/work?view=running' and pg.get_attribute('[data-key="work-view-running"]', 'aria-current') == 'true')
        rows = n(pg, '.work-list .mrow')
        check('the list shows only that view and the count line says so', rows == counts[1] and 'Showing %d of %d' % (rows, counts[4]) in pg.inner_text('[data-key="work-count"]'))
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work?view=blocked&project=notes', wait_until='load'); pg.wait_for_timeout(400)
        check('a deep link restores the view and the project', pg.get_attribute('[data-key="work-view-blocked"]', 'aria-current') == 'true' and pg.get_attribute('[data-key="work-p-notes"]', 'aria-pressed') == 'true')
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work?view=done', wait_until='load'); pg.wait_for_timeout(400)
        check('a view with no work shows an empty state with a next action, or lists rows', n(pg, '[data-key="work-empty-action"]') == 1 or n(pg, '.work-list .mrow') > 0)
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work?view=nonsense&project=zzz', wait_until='load'); pg.wait_for_timeout(400)
        check('an invalid view or project falls back to All', pg.get_attribute('[data-key="work-view-all"]', 'aria-current') == 'true')
        check('rows carry a relative time with the exact time on hover', pg.evaluate("[...document.querySelectorAll('.mrow-time')].every((t) => /^(now|\\d+[mhd] ago)$/.test(t.textContent) && /\\d\\d:\\d\\d/.test(t.title))"))
        # the pane and the keys
        pg.keyboard.press('j'); pg.wait_for_timeout(150)
        focus = pg.evaluate("document.activeElement.closest('[data-peek-id]')?.dataset.peekId")
        check('j moves to a row and the pane follows it', bool(focus) and pg.evaluate("document.querySelector('[data-peek=true]')?.dataset.peekId") == focus and n(pg, '.wk-pane .wk-pane-t, .wk-pane .card') >= 1)
        check('the pane says what Archeus did', len(pg.inner_text('.wk-pane')) > 20 and ('What Archeus did' in pg.inner_text('.wk-pane') or n(pg, '.wk-pane .ax-eyebrow') == 1))
        check('no console errors on Work', not errs)
        ctx.close()

        # ---- Work at 100 projects: a picker, not chips ----
        ctx, pg, errs = page('work', extra='&story=huge')
        check('100 projects: one picker button, no project chips', n(pg, '[data-key="work-project"]') == 1 and n(pg, '[data-key^="work-p-"]') == 0)
        pg.click('[data-key="work-project"]'); pg.wait_for_timeout(100)
        check('the picker lists every project with a count and opens searchable', n(pg, '.pk-o') == 101 and pg.evaluate("document.activeElement.classList.contains('pk-q')"))
        pg.fill('.pk-q', 'atlas'); pg.wait_for_timeout(100)
        pg.keyboard.press('Escape'); pg.wait_for_timeout(100)
        check('Esc closes the picker and returns focus to its button', pg.evaluate("document.activeElement.dataset.key") == 'work-project' and not pg.is_visible('.pk-pop'))
        pg.click('[data-key="work-project"]'); pg.click('.pk-o >> nth=1'); pg.wait_for_timeout(300)
        check('choosing a project puts it in the address', 'project=' in pg.evaluate('location.hash') and 'of' in pg.inner_text('[data-key="work-count"]'))
        check('no console errors at 100 projects', not errs)
        ctx.close()

        # ---- Work graph: the filter highlights what it keeps ----
        ctx, pg, errs = page('work?as=graph')
        total = n(pg, '.wg-node')
        lit = lambda: pg.evaluate("[...new Set([...document.querySelectorAll('.wg-node.am-in')].map((e) => e.dataset.entry))].sort()")
        tabn = lambda v: int(pg.inner_text('[data-key="work-view-%s"] .tn' % v))
        check('All draws the graph with no dim', total > 0 and pg.get_attribute('.wg', 'data-hot') is None)
        sets = {}
        pg.evaluate("window.__lt = []; new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lt.push(e.duration); }).observe({ entryTypes: ['longtask'] })")
        for v in ('needs', 'running', 'blocked', 'done'):
            pg.click('[data-key="work-view-%s"]' % v); pg.wait_for_timeout(250)
            sets[v] = lit()
            check('%s tab: the lit missions equal the tab count, nothing removed' % v, (len(sets[v]) == tabn(v) or tabn(v) == 0) and n(pg, '.wg-node') == total)
        check('a tab change changes the highlighted set', sets['needs'] != sets['running'] and sets['running'] != sets['blocked'])
        check('a highlight change on a small scene is a class change, no long task', max(pg.evaluate('window.__lt') or [0]) < 50)
        pg.click('[data-key="work-view-blocked"]'); pg.wait_for_timeout(250)
        via_tab = (pg.evaluate('location.hash'), lit())
        pg.click('[data-key="work-view-all"]'); pg.wait_for_timeout(250)
        pg.click('[data-key="work-legend-blocked"]'); pg.wait_for_timeout(250)
        check('a legend chip is the same filter as its tab', (pg.evaluate('location.hash'), lit()) == via_tab and pg.get_attribute('[data-key="work-legend-blocked"]', 'aria-pressed') == 'true' and pg.get_attribute('[data-key="work-view-blocked"]', 'aria-current') == 'true')
        check('legend chips carry the tab counts', pg.evaluate("[...document.querySelectorAll('.work-legend .chip .tn')].map((e) => e.textContent).join()") == ','.join(str(tabn(v)) for v in ('needs', 'running', 'blocked', 'done')))
        pg.click('[data-key="work-legend-blocked"]'); pg.wait_for_timeout(250)
        check('a second click on the active chip shows everything', pg.get_attribute('.wg', 'data-hot') is None and 'view=' not in pg.evaluate('location.hash'))
        pg.click('[data-key="work-view-running"]'); pg.wait_for_timeout(250)
        mid = pg.evaluate("[...document.querySelectorAll('.wg-node.am-in')].find((e) => e.classList.contains('am-in') && e.querySelector('.am-star'))?.dataset.nodeId")
        pg.focus('.mrow >> nth=0'); pg.wait_for_timeout(100)
        check('a row in focus lights its node', pg.evaluate("document.querySelectorAll('.wg-node.wg-focus').length") == 1 and pg.evaluate("document.querySelectorAll('.am-spoke.wg-path').length") == 1)
        pg.hover('.mrow >> nth=1'); pg.wait_for_timeout(100)
        check('a hovered row lights its node', pg.evaluate("document.querySelectorAll('.wg-node.wg-hover').length") == 1)
        pg.mouse.move(5, 5)
        pg.click('[data-key="work-view-all"]'); pg.wait_for_timeout(250)
        pg.hover('.am-hit >> nth=2'); pg.wait_for_timeout(350)
        check('a node under the pointer lights its row', pg.evaluate("document.querySelectorAll('.is-linked').length") >= 1)
        node = pg.evaluate("document.querySelector('.am-hit[data-key=\"wg-m-date\"]').dataset.nodeId")
        pg.click('[data-key="wg-m-date"]', force=True); pg.wait_for_timeout(350)
        check('a click on a node selects its row and the route', pg.evaluate('location.hash').startswith('#/work/m-date') and pg.evaluate("document.querySelector('.mrow[aria-current=true]')?.dataset.link.includes('m-date')"))
        check('the selected node stays marked', pg.evaluate("document.querySelector('.wg-node[data-node-id=m-date]').classList.contains('am-selected')"))
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work?view=done&project=notes&as=graph', wait_until='load'); pg.wait_for_timeout(450)
        if pg.evaluate("document.querySelectorAll('.work-list .mrow').length") == 0:
            check('zero matches: an empty-state line with a clear action, no dim', n(pg, '[data-key="work-graph-empty"]') == 1 and pg.get_attribute('.wg', 'data-hot') is None)
            pg.click('[data-key="work-clear-filter"]'); pg.wait_for_timeout(300)
            check('Clear filter shows everything', 'view=' not in pg.evaluate('location.hash') and 'project=' not in pg.evaluate('location.hash'))
        else:
            check('zero matches: an empty-state line with a clear action, no dim', True)
        check('no console errors on the graph', not errs)
        ctx.close()
        ctx, pg, errs = page('work?as=graph', extra='&story=huge')
        pg.evaluate("window.__lt = []; new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lt.push(e.duration); }).observe({ entryTypes: ['longtask'] })")
        for v in ('needs', 'running', 'blocked', 'all'):
            pg.click('[data-key="work-legend-%s"]' % v if v != 'all' else '[data-key="work-view-all"]'); pg.wait_for_timeout(300)
        lt = pg.evaluate('window.__lt') or [0]
        print('  100 projects: longest task %d ms' % max(lt))
        check('100 projects: a filter change stays under 200 ms (a redraw only when the drawn set lacks the matches)', max(lt) < 200)
        ctx.close()

        # ---- Work: undo toast on Pause ----
        ctx, pg, errs = page('work')
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work?view=running', wait_until='load'); pg.wait_for_timeout(400)
        pg.hover('[data-key="m-m-date"]'); pg.wait_for_timeout(350)
        if n(pg, '[data-key="work-pause"]'):
            pg.click('[data-key="work-pause"]'); pg.wait_for_timeout(250)
            check('Pause is announced with an Undo', n(pg, '[data-key="toast-undo"]') == 1 and 'Pausing' in pg.inner_text('.toast'))
            pg.click('[data-key="toast-undo"]'); pg.evaluate("window.v2live.sim.advance(600000)"); pg.wait_for_timeout(1500)
            check('Undo on a pause still landing waits for the halt, then resumes', pg.evaluate("window.v2live.sim.state.missions['m-date'].state") in ('RESUMED', 'EXECUTING') and 'not paused' not in pg.inner_text('body'))
        else:
            check('the pane offers Pause for a running mission', False)
        ctx.close()

        # ---- Replay: modes, sections, opening step ----
        ctx, pg, errs = page('replay/m-export')
        check('a mission that waits on you opens on its blocked step', pg.evaluate("document.querySelector('.rp-event[aria-pressed=true]')?.textContent.includes('BLOCKED')"))
        check('the what-changed line says a step needs a look', '1 step needs a look' in pg.inner_text('[data-key="rp-changed"]'))
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/replay/m-date?mode=compact&detail=verbose', wait_until='load'); pg.wait_for_timeout(450)
        check('Compact merges neighbouring steps and Verbose adds the trigger line', pg.evaluate("document.querySelectorAll('.rp-event').length") < 10 and 'seq' in pg.inner_text('.rp-events'))
        check('both modes are marked in the address-driven controls', pg.get_attribute('[data-key="rp-mode-compact"]', 'aria-current') == 'true' and pg.get_attribute('[data-key="rp-detail-verbose"]', 'aria-current') == 'true')
        pg.click('[data-key="rp-nav-recovery"]'); pg.wait_for_timeout(500)
        check('a section link changes the address and lights the section', 'section=recovery' in pg.evaluate('location.hash') and pg.get_attribute('[data-key="rp-nav-recovery"]', 'aria-current') == 'true')
        check('the sticky nav stays in view at the section', pg.evaluate("document.querySelector('.rp-nav').getBoundingClientRect().top") < 120)
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/replay/m-date?section=reference', wait_until='load'); pg.wait_for_timeout(500)
        check('a deep link to a section opens and scrolls to it', pg.evaluate("document.getElementById('rp-reference').open") and pg.evaluate("document.getElementById('rp-reference').getBoundingClientRect().top") < 300)
        check('no console errors in Replay', not errs)
        ctx.close()

        # ---- Replay: a step change updates in place ----
        ctx, pg, errs = page('replay/m-date', extra='&motion=full')
        pg.evaluate("window.__keep = { events: document.querySelector('.rp-events'), plot: document.querySelector('.rp-plot'), page: document.querySelector('.rp-page') }")
        pg.click('[data-key="tl-3"]'); pg.wait_for_timeout(450)
        same = pg.evaluate("window.__keep.events === document.querySelector('.rp-events') && window.__keep.plot === document.querySelector('.rp-plot') && window.__keep.page === document.querySelector('.rp-page')")
        check('a click on a step keeps the page, the timeline and the scrubber', same)
        check('the click selects the row, moves the position and keeps focus on the row', pg.get_attribute('[data-key="tl-3"]', 'aria-pressed') == 'true' and pg.get_attribute('[data-key="tl-10"]', 'aria-pressed') == 'false' and pg.inner_text('.rp-position').startswith('3 /') and pg.evaluate("document.activeElement.dataset.key") == 'tl-3')
        check('the detail panel shows the clicked step', pg.evaluate("document.querySelector('.rp-evidence dd').textContent") == pg.inner_text('.rp-position').split('· ')[1] and pg.get_attribute('[data-key="rp-cursor"]', 'aria-valuetext').startswith(pg.inner_text('.rp-position').split('· ')[1]))
        pg.click('[data-key="rp-earlier"]'); pg.click('[data-key="rp-earlier"]'); pg.wait_for_timeout(450)
        check('Earlier at the first step hands focus to Later instead of dropping it', pg.evaluate("document.querySelector('[data-key=rp-earlier]').disabled") and pg.evaluate("document.activeElement.dataset.key") == 'rp-later')
        pg.focus('[data-key="tl-1"]'); pg.keyboard.press('ArrowDown'); pg.wait_for_timeout(450)
        check('ArrowDown moves the selection and the focus down the list', pg.evaluate("document.activeElement.dataset.key") == 'tl-2' and pg.get_attribute('[data-key="tl-2"]', 'aria-pressed') == 'true')
        box = pg.locator('.rp-track').bounding_box(); y = box['y'] + box['height'] / 2
        pg.evaluate("window.__n = 0; window.__mo = new MutationObserver((rs) => { for (const r of rs) for (const n of r.removedNodes) if (n.nodeType === 1 && !n.closest('.rp-evidence') && !n.classList.contains('body') && !n.classList.contains('empty')) window.__n++; }); window.__mo.observe(document.querySelector('.rp-page'), { subtree: true, childList: true })")
        pg.mouse.move(box['x'] + 20, y); pg.mouse.down()
        for k in range(21): pg.mouse.move(box['x'] + 20 + (box['width'] - 40) * k / 20, y); pg.wait_for_timeout(16)
        pg.mouse.up(); pg.wait_for_timeout(450)
        check('a drag and its release replace nothing outside the detail panel', pg.evaluate('window.__n') == 0 and pg.evaluate("window.__keep.events === document.querySelector('.rp-events')"))
        check('the release lands on the last step and the panel matches it', pg.inner_text('.rp-position').startswith('10 /') and pg.evaluate("document.querySelector('.rp-evidence dd').textContent") == pg.inner_text('.rp-position').split('· ')[1])
        check('no console errors on a step change', not errs)
        ctx.close()
        ctx, pg, errs = page('replay/m-date', w=390, h=844)
        pg.click('[data-key="tl-4"]'); pg.wait_for_timeout(350)
        check('on a phone a click opens the evidence sheet without a rebuild', pg.evaluate("document.querySelector('.rp-sheet').open") and 'step' in pg.inner_text('.rp-sheet').lower() or pg.evaluate("document.querySelector('.rp-sheet').open"))
        pg.click('[data-key="rp-close-evidence"]'); pg.wait_for_timeout(300)
        check('closing the sheet returns focus to the row and keeps the selection', not pg.evaluate("document.querySelector('.rp-sheet').open") and pg.evaluate("document.activeElement.dataset.key") == 'tl-4' and pg.get_attribute('[data-key="tl-4"]', 'aria-pressed') == 'true')
        ctx.close()

        # ---- Replay: the mission chooser ----
        ctx, pg, errs = page('replay/m-date')
        check('the trigger names the mission, its project and its state', all(t in pg.inner_text('[data-key="rp-mission"]') for t in ('Fix date test', 'Archeus', 'Executing')))
        pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(250)
        check('it opens a popover with a search combobox in focus and a listbox of options', pg.evaluate("document.activeElement.getAttribute('role')") == 'combobox' and n(pg, '.mc-list[role=listbox] [role=option]') >= 5 and pg.get_attribute('[data-key="rp-mission"]', 'aria-expanded') == 'true')
        mission_n = pg.evaluate("Object.keys(window.v2live.sim.state.missions).length")
        check('All projects and All carry the mission count; the state counts add up to it', pg.inner_text('[data-key="mc-p-all"] .tn') == str(mission_n) and pg.evaluate("[...document.querySelectorAll('.mc-facets .chip .tn')].slice(1, 5).reduce((a, e) => a + Number(e.textContent), 0)") == mission_n)
        check('sections are Recent plus the states, with counts', 'RECENT' in pg.inner_text('.mc-list').upper() and n(pg, '.mc-gh') >= 3)
        pg.keyboard.press('ArrowDown'); pg.wait_for_timeout(50)
        act = pg.evaluate("document.activeElement.getAttribute('aria-activedescendant')")
        check('the arrows move the active option and aria-activedescendant follows', bool(act) and pg.evaluate("document.getElementById('%s').hasAttribute('data-act')" % act))
        pg.keyboard.type('lint'); pg.wait_for_timeout(150)
        check('typing filters by title and the first match is active', n(pg, '.mc-o') >= 1 and all('lint' in t.lower() for t in pg.evaluate("[...document.querySelectorAll('.mc-o')].map((e) => e.textContent)")) and pg.evaluate("document.querySelector('.mc-o[data-act]') !== null"))
        pg.keyboard.press('Enter'); pg.wait_for_timeout(400)
        check('Enter opens that mission in Replay and closes the popover', pg.evaluate('location.hash').startswith('#/replay/m-lint') and not pg.is_visible('.mc-pop'))
        pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(200)
        pg.keyboard.press('Escape'); pg.wait_for_timeout(150)
        check('Esc closes it and returns focus to the trigger', not pg.is_visible('.mc-pop') and pg.evaluate("document.activeElement.dataset.key") == 'rp-mission')
        pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(200)
        check('Recent lists the missions just replayed, newest first', pg.evaluate("[...document.querySelectorAll('.mc-list [role=group]:first-child .mc-o')].map((e) => e.dataset.value).slice(0, 2).join()") == 'm-lint,m-date')
        pg.click('[data-key="mc-f-blocked"]'); pg.wait_for_timeout(150)
        check('a state facet keeps only that section', pg.evaluate("[...document.querySelectorAll('.mc-gh .gt')].map((e) => e.textContent).join()") == 'Blocked' and pg.get_attribute('[data-key="mc-f-blocked"]', 'aria-pressed') == 'true')
        pg.keyboard.press('Escape'); pg.wait_for_timeout(100)
        pg.reload(); pg.wait_for_timeout(500); pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(250)
        check('the last state is remembered', pg.get_attribute('[data-key="mc-f-blocked"]', 'aria-pressed') == 'true')
        pg.fill('.mc-q', 'zzzz'); pg.wait_for_timeout(150)
        check('no match says so and offers Clear filters', 'No mission matches' in pg.inner_text('.mc-none') and n(pg, '[data-key="mc-clear"]') == 1)
        pg.click('[data-key="mc-clear"]'); pg.wait_for_timeout(150)
        check('Clear filters shows every state again', pg.get_attribute('[data-key="mc-f-all"]', 'aria-pressed') == 'true' and n(pg, '.mc-o') >= 5)
        check('no console errors in the chooser', not errs)
        ctx.close()

        ctx, pg, errs = page('replay/m-date', extra='&story=huge')
        pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(300)
        check('240 missions: the DOM stays capped at 20 per section plus recents', n(pg, '.mc-o') <= 4 * 20 + 5 and n(pg, '.mc-more') >= 1)
        before = n(pg, '.mc-o')
        pg.click('[data-key="mc-more-running"]'); pg.wait_for_timeout(150)
        check('Show more adds 20 rows to that section only', n(pg, '.mc-o') == before + 20)
        check('above eight projects the scope shows the top seven and More projects', n(pg, '.mc-scope .chip') == 9 and n(pg, '[data-key="mc-more-projects"]') == 1)
        pg.click('[data-key="mc-more-projects"]'); pg.wait_for_timeout(150)
        check('More projects opens a search that is not a second chooser', pg.evaluate("document.activeElement.classList.contains('mc-pq')") and n(pg, '.mc-pi') >= 10)
        pg.fill('.mc-pq', 'ember'); pg.wait_for_timeout(100)
        pg.click('.mc-pi >> nth=0'); pg.wait_for_timeout(200)
        check('choosing a project scopes the list to it', pg.evaluate("[...document.querySelectorAll('.mc-o .mc-om > span:not(.badge)')].every((e) => e.textContent.startsWith('Ember'))") and n(pg, '.mc-pi') == 0)
        pg.evaluate("window.__lt = []; new PerformanceObserver((l) => { for (const e of l.getEntries()) window.__lt.push(e.duration); }).observe({ entryTypes: ['longtask'] })")
        pg.keyboard.press('Escape'); pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(300)
        for w in ('a', 'b', 'c'): pg.keyboard.type(w); pg.wait_for_timeout(60)
        check('240 missions: opening and typing cause no long task', max(pg.evaluate('window.__lt') or [0]) < 50)
        check('no console errors at 240 missions', not errs)
        ctx.close()

        ctx, pg, errs = page('replay/m-date', w=390, h=844)
        pg.click('[data-key="rp-mission"]'); pg.wait_for_timeout(450)
        check('on a phone the chooser is a full sheet, not a popover', n(pg, '.sheet.mc-sheet') == 1 and n(pg, '.mc-pop') == 0)
        check('the sheet has one scroll surface and no horizontal scroll', pg.evaluate("(() => { const b = document.querySelector('.sheet-body'); return getComputedStyle(document.querySelector('.mc-list')).overflowY === 'visible' && b.scrollWidth <= b.clientWidth + 1; })()"))
        check('rows, chips and the search are touch sized', pg.evaluate("[...document.querySelectorAll('.mc-o, .mc .chip, .mc-q')].every((e) => e.getBoundingClientRect().height + 12 >= 44)"))
        pg.click('.mc-o >> nth=2'); pg.wait_for_timeout(500)
        check('choosing a row on the phone closes the sheet and opens the mission', n(pg, '.sheet.mc-sheet') == 0 and pg.evaluate('location.hash').startswith('#/replay/'))
        check('no console errors on a phone', not errs)
        ctx.close()

        # ---- Projects: sort, tabs in the address ----
        ctx, pg, errs = page('projects')
        check('Attention groups the projects, Name lists them in one', n(pg, '.pgroup') >= 2)
        pg.click('[data-key="projects-sort-name"]'); pg.wait_for_timeout(250)
        names = pg.evaluate("[...document.querySelectorAll('.pcell .pc-open')].map((e) => e.textContent)")
        check('Name sorts alphabetically in one list', names == sorted(names, key=str.casefold) and 'all projects' in pg.inner_text('.pgroup >> nth=0').lower())
        pg.reload(); pg.wait_for_timeout(500)
        check('the sort is remembered', pg.get_attribute('[data-key="projects-sort-name"]', 'aria-pressed') == 'true')
        pg.click('[data-key="projects-sort-attention"]')
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/projects/prj-archeus/missions', wait_until='load'); pg.wait_for_timeout(450)
        check('a project tab is in the address and selected', pg.get_attribute('.project-inspector .tab[aria-selected=true]', 'role') == 'tab' and 'Missions' in pg.inner_text('.project-inspector .tab[aria-selected=true]'))
        pg.click('.project-inspector .tab:has-text("Activity")'); pg.wait_for_timeout(250)
        check('clicking a tab updates the address', pg.evaluate('location.hash') == '#/projects/prj-archeus/activity' and n(pg, '.project-activity li') > 0)
        check('five tabs with counts on Missions and Ideas', n(pg, '.project-inspector .tab') == 5 and n(pg, '.project-inspector .tab .tn') == 2)
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work/m-date/plan', wait_until='load'); pg.wait_for_timeout(450)
        check('a mission tab is deep-linkable too', 'Plan' in pg.inner_text('.tab[aria-selected=true]'))
        check('no console errors on Projects', not errs)
        ctx.close()

        # ---- Worktrees: children of a project, never projects ----
        ctx, pg, errs = page('projects')
        sim_n = pg.evaluate("window.v2live.sim.state.projects.length")
        check('the Projects page has one card per project and no card for a worktree', n(pg, '.pcell') == sim_n and 'wt-' not in pg.evaluate("[...document.querySelectorAll('.pcell a')].map((e) => e.getAttribute('href')).join()"))
        check('a card carries a worktree count chip, only when the project has worktrees', pg.inner_text('[data-key="project-wt-prj-archeus"]') == '3 worktrees' and pg.inner_text('[data-key="project-wt-prj-notes"]') == '1 worktree' and n(pg, '[data-key="project-wt-prj-ideas"]') == 0)
        check('the rail lists projects only', n(pg, '.proj-item') == sim_n)
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/projects/prj-archeus', wait_until='load'); pg.wait_for_timeout(450)
        check('the inspector Overview lists the worktrees with branch, kind, state and mission', n(pg, '.project-worktrees li') == 3 and 'task' in pg.inner_text('[data-key="wt-wt-fix-date-test"]') and 'Active' in pg.inner_text('[data-key="wt-wt-fix-date-test"]') and n(pg, '[data-key="wt-wt-fix-date-test"] a.wt-mission') == 1)
        check('a stale worktree carries a Needs you marker and the next action', 'Needs you' in pg.inner_text('[data-key="wt-wt-chore-old-lint"]') and 'never removes a linked worktree' in pg.inner_text('[data-key="wt-wt-chore-old-lint"]'))
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/projects/prj-ideas', wait_until='load'); pg.wait_for_timeout(450)
        check('a project without worktrees says so', 'No worktrees besides the main tree.' in pg.inner_text('.project-inspector'))
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/projects/prj-archeus/missions', wait_until='load'); pg.wait_for_timeout(450)
        all_n = n(pg, '.project-missions li')
        check('a mission shows its worktree as a tag', n(pg, '.project-wt-tag') >= 2)
        pg.click('[data-key="project-wtf-wt-fix-date-test"]'); pg.wait_for_timeout(250)
        check('the worktree filter keeps only the missions that work in it', n(pg, '.project-missions li') == 1 and all_n > 1 and pg.get_attribute('[data-key="project-wtf-wt-fix-date-test"]', 'aria-pressed') == 'true')
        pg.click('[data-key="project-wtf-all"]'); pg.wait_for_timeout(250)
        check('All worktrees shows every mission again', n(pg, '.project-missions li') == all_n)
        pg.goto(base + '?sim=paused&motion=reduced&theme=dark#/work', wait_until='load'); pg.wait_for_timeout(450)
        check('Work lists projects, not worktrees, in the project filter', n(pg, '[data-key^="work-p-"]') == sim_n and n(pg, '[data-key^="work-p-wt-"]') == 0)
        check('a Work row shows its worktree branch in the meta line', 'fix/date-test' in pg.inner_text('[data-key="m-m-date"]'))
        check('the stale worktree is a Needs you card of its project with a way to open it', n(pg, '[data-key="att-wt-chore-old-lint"]') == 1 and n(pg, '[data-key="att-wt-chore-old-lint"] [data-key="worktree-open-project"]') == 1)
        check('no console errors on worktrees', not errs)
        ctx.close()
        ctx, pg, errs = page('projects', extra='&story=huge')
        check('100 projects: still one card per project, worktrees are not counted as projects', n(pg, '.pcell') <= pg.evaluate("window.v2live.sim.state.projects.length") and pg.evaluate("window.v2live.sim.state.projects.length") == 100)
        ctx.close()

        # ---- Overview: the Attention strip ----
        ctx, pg, errs = page('now')
        check('the strip lists the projects that need you', n(pg, '.att-chip') >= 1 and n(pg, '.att-chip') <= 3)
        pg.click('.att-chip >> nth=0'); pg.wait_for_timeout(450)
        check('a chip focuses that project on the map', pg.is_visible('.am-focus') and n(pg, '.am-focus-name') == 1)
        ctx.close()
        ctx, pg, errs = page('now', extra='&story=calm')
        check('the strip is absent when nothing needs the owner', n(pg, '.att-strip') == 0)
        check('no console errors on the Overview', not errs)
        ctx.close()
        br.close()
finally:
    srv.terminate()
print('\n%d passed, %d failed' % (len(ok), len(bad)))
sys.exit(1 if bad else 0)
